local SealRingMaker = {}
local PRODUCTS = {
    iron_seal_ring = { name = "Železen pečatni prstan", ironCost = 1, time = 1, cost = 8, authority = 2, description = "Železen pečatni prstan za nižje uradnike." },
    brass_seal_ring = { name = "Medeninast pečatni prstan", brassCost = 1, time = 2, cost = 24, authority = 4, prestige = 1, description = "Medeninast pečatni prstan za obrtnike." },
    silver_seal_ring = { name = "Srebrn pečatni prstan", silverCost = 1, time = 3, cost = 70, authority = 8, prestige = 3, description = "Srebrn pečatni prstan za meščane." },
    gold_seal_ring = { name = "Zlat pečatni prstan", goldCost = 1, time = 4, cost = 180, authority = 14, prestige = 7, happiness = 1, description = "Zlat pečatni prstan za viteze." },
    jewel_seal_ring = { name = "Draguljni pečatni prstan", goldCost = 1, silverCost = 1, jewelCost = 1, time = 6, cost = 420, authority = 22, prestige = 14, happiness = 2, description = "Z draguljem okrašen pečatni prstan za plemiče." },
    royal_signet_ring = { name = "Kraljevski signetni prstan", goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 1, time = 9, cost = 950, authority = 40, prestige = 32, happiness = 6, description = "Kraljevski signetni prstan z biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Prtanarska delavnica", cost = { gold = 250, wood = 100 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Prtanarska kovačija", cost = { gold = 750, wood = 200, stone = 180, silver = 8 }, upkeep = 18, qualityBonus = 18 },
    engraving_room = { name = "Vgravirnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 30, jewel = 6 }, upkeep = 40, qualityBonus = 30 },
    royal_ring_atelier = { name = "Kraljevski atelje prstanov", cost = { gold = 6000, wood = 500, stone = 700, gold = 60, jewel = 20 }, upkeep = 110, qualityBonus = 55, prestigeBonus = 30 },
}
SealRingMaker.ironStock = 12; SealRingMaker.brassStock = 8; SealRingMaker.silverStock = 8; SealRingMaker.goldStock = 6; SealRingMaker.jewelStock = 6; SealRingMaker.pearlStock = 4
SealRingMaker.productStock = {}; SealRingMaker.buildings = {}; SealRingMaker.maker = nil; SealRingMaker.activeMaking = {}; SealRingMaker.totalProducts = 0; SealRingMaker.dayTimer = 0
function SealRingMaker.init() SealRingMaker.ironStock=12; SealRingMaker.brassStock=8; SealRingMaker.silverStock=8; SealRingMaker.goldStock=6; SealRingMaker.jewelStock=6; SealRingMaker.pearlStock=4; SealRingMaker.productStock={}; SealRingMaker.buildings={}; SealRingMaker.maker=nil; SealRingMaker.activeMaking={}; SealRingMaker.totalProducts=0; SealRingMaker.dayTimer=0; print("[SealRingMaker] Royal Seal Ring Maker System initialized (6 products, 4 buildings)") end
function SealRingMaker.hireMaker(n,s) s=s or math.random(50,90); local c=450+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SealRingMaker.maker={name=n or ("Prtanar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prtanar najet: %s (spretnost: %d)",SealRingMaker.maker.name,s),"success") end; return true end
function SealRingMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SealRingMaker.build(id) local ok,e=SealRingMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SealRingMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SealRingMaker.getQualityBonus() local b=0; for _,bd in ipairs(SealRingMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SealRingMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SealRingMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and SealRingMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and SealRingMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SealRingMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SealRingMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SealRingMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SealRingMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SealRingMaker.maker then return false,"Potreben prtanar" end; return true end
function SealRingMaker.make(pt,qty) qty=qty or 1; local ok,e=SealRingMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SealRingMaker.ironStock=SealRingMaker.ironStock-d.ironCost*qty end; if d.brassCost then SealRingMaker.brassStock=SealRingMaker.brassStock-d.brassCost*qty end; if d.silverCost then SealRingMaker.silverStock=SealRingMaker.silverStock-d.silverCost*qty end; if d.goldCost then SealRingMaker.goldStock=SealRingMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SealRingMaker.jewelStock=SealRingMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SealRingMaker.pearlStock=SealRingMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SealRingMaker.maker then t=math.max(1,t-math.floor(SealRingMaker.maker.skill/12)) end; table.insert(SealRingMaker.activeMaking,{id="ring_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,authority=d.authority or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SealRingMaker.completeMaking(m) local q=1.0+(SealRingMaker.getQualityBonus()/100); if SealRingMaker.maker then q=q+(SealRingMaker.maker.skill/180) end; q=math.min(2.0,q); SealRingMaker.productStock[m.productType]=(SealRingMaker.productStock[m.productType] or 0)+m.quantity; SealRingMaker.totalProducts=SealRingMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SealRingMaker.maker then SealRingMaker.maker.itemsMade=SealRingMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then SealRingMaker.maker.skill=math.min(100,SealRingMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prstan izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sealring.completed",{productName=m.productName,authority=m.authority}) end end
function SealRingMaker.update(dt) if not _G.state then return end; SealRingMaker.dayTimer=SealRingMaker.dayTimer+dt; if SealRingMaker.dayTimer>=30 then SealRingMaker.dayTimer=0; for i=#SealRingMaker.activeMaking,1,-1 do local m=SealRingMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SealRingMaker.completeMaking(m); table.remove(SealRingMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SealRingMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SealRingMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SealRingMaker.getStats() return {ironStock=SealRingMaker.ironStock,brassStock=SealRingMaker.brassStock,silverStock=SealRingMaker.silverStock,goldStock=SealRingMaker.goldStock,jewelStock=SealRingMaker.jewelStock,pearlStock=SealRingMaker.pearlStock,productStock=SealRingMaker.productStock,numBuildings=#SealRingMaker.buildings,hasMaker=SealRingMaker.maker~=nil,makerName=SealRingMaker.maker and SealRingMaker.maker.name or "—",makerSkill=SealRingMaker.maker and SealRingMaker.maker.skill or 0,activeMaking=#SealRingMaker.activeMaking,totalProducts=SealRingMaker.totalProducts} end
return SealRingMaker
